mapper.select:
SELECT COUNT(1)
FROM ultary_neighbor
WHERE status = 'ACCEPTED'
  AND (
	(requester_user_no = #{viewerUserNo} AND receiver_user_no = #{ownerUserNo})
	OR (
		requester_user_no = #{ownerUserNo}
		AND receiver_user_no = #{viewerUserNo}
		AND followed_back = 1
	)
  )

